import re
from typing import List


class SplitSentence:

    SENTENCE_SPLIT_PATTERN = re.compile(r'(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s')
    NON_ALPHABETIC_PATTERN = re.compile(r'[^a-zA-Z\s]')

    def split_sentences(self, sentences_string: str) -> List[str]:
        return self.SENTENCE_SPLIT_PATTERN.split(sentences_string)

    def count_words(self, sentence: str) -> int:
        cleaned_sentence = self.NON_ALPHABETIC_PATTERN.sub('', sentence)
        return self._count_non_empty_tokens(cleaned_sentence)

    def _count_non_empty_tokens(self, text: str) -> int:
        return len(text.split())

    def process_text_file(self, sentences_string: str) -> int:
        sentences = self.split_sentences(sentences_string)
        return self._find_max_word_count(sentences)

    def _find_max_word_count(self, sentences: List[str]) -> int:
        return max((self.count_words(sentence) for sentence in sentences), default=0)
